parameters.jsCode:
// Parse the model's JSON text block and return it verbatim to the backend.
// The BACKEND validates and (after user confirmation) writes the expense.
const content = $json.content?.[0]?.text ?? '{}';
let parsed;
try { parsed = JSON.parse(content.replace(/```json|```/g, '').trim()); }
catch { parsed = { warnings: ['Could not parse receipt output'] }; }
return [{ json: parsed }];
